import{_ as t,o as s,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Material Design","description":"Material Design 1.1.0 pour Studio 0.1.292 avec DE/EN/FR et mises à jour compatibles.","frontmatter":{"title":"Material Design","description":"Material Design 1.1.0 pour Studio 0.1.292 avec DE/EN/FR et mises à jour compatibles."},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/materialdesign.md","filePath":"fr/projects/grafik-visual-studio/materialdesign.md","lastUpdated":1793447386000}'),r={name:"fr/projects/grafik-visual-studio/materialdesign.md"};function n(o,e,l,d,u,c){return s(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="material-design" tabindex="-1">Material Design <a class="header-anchor" href="#material-design" aria-label="Permalink to &quot;Material Design&quot;">​</a></h1><p>Depuis <strong>Studio 0.1.295</strong>, les icônes et leur symbole remplissent le cadre de la barre latérale et du sélecteur. Graphiques et réglages conservés ; aucune mise à jour du paquet nécessaire. <a href="/fr/projects/grafik-visual-studio/interaktiv">Nouveautés interactives</a>.</p><p><strong>Paquet 1.1.0 · Studio 0.1.292 ou plus récent · 49 widgets · MIT.</strong> Moteurs indépendants inspirés de <a href="https://github.com/typhosj/ioBroker.vis2-materialdesign" target="_blank" rel="noreferrer">ioBroker VIS2 Material Design de typhosj/Scrounger</a>. Les icônes MDI originales restent des SVG locaux. Identifiant technique : <code>ugso.materialdesign</code>.</p><p><a href="/projects/grafik-visual-studio/materialdesign">Deutsch</a> · <a href="/en/projects/grafik-visual-studio/materialdesign">English</a> · <a href="https://github.com/rockbaer2007/ha-grafik-visual-studio-materialdesign" target="_blank" rel="noreferrer">Code source</a></p><h2 id="installation-et-conservation-des-reglages" tabindex="-1">Installation et conservation des réglages <a class="header-anchor" href="#installation-et-conservation-des-reglages" aria-label="Permalink to &quot;Installation et conservation des réglages&quot;">​</a></h2><ol><li>Exporter le projet Studio existant en JSON.</li><li>Mettre Studio à jour vers <strong>0.1.292 ou plus récent</strong>, puis redémarrer.</li><li><a href="https://github.com/rockbaer2007/ha-grafik-visual-studio-materialdesign/blob/main/dist/ugso.materialdesign-1.1.0.wg" target="_blank" rel="noreferrer">Télécharger Material Design 1.1.0</a>. Installer via <strong>Paramètres → Paquets de widgets → Local</strong>, ou le lien direct du fichier GitHub.</li><li>La mise à jour est additive. Recharger la page et vérifier le projet existant.</li></ol><p>L’installation <strong>ne réécrit aucun fichier de projet</strong>. Champs, valeurs par défaut, ordre et identifiants techniques restent protégés. De nouveaux champs/groupes et choix sont ajoutés. Couleurs, textes, dimensions, entités et groupes désactivés restent enregistrés. Les anciens paquets publiés restent disponibles.</p><p>Les anciens widgets <strong>State Multi</strong> conservent leur cycle. Le mode multicible se choisit explicitement. Les anciennes Advanced Views gardent leurs associations ; noms/ID et indices numériques sont des modes supplémentaires. Les nouveaux widgets incluent les modes de l’original. Changer de style ne modifie pas les cibles.</p><h2 id="langues-et-apparence" tabindex="-1">Langues et apparence <a class="header-anchor" href="#langues-et-apparence" aria-label="Permalink to &quot;Langues et apparence&quot;">​</a></h2><p><strong>Langue Material</strong> suit Studio ou choisit <strong>allemand, anglais ou français</strong> pour le widget et ses propriétés Material. Les textes personnels et identifiants ne sont pas traduits. L’interface générale du Studio reste DE/EN ; le français concerne ici Material.</p><p><strong>Classique</strong>, <strong>Material 3</strong> et <strong>Défaut du projet</strong> restent disponibles. Les couleurs suivent la page ou imposent Clair/Sombre. Couleurs, tailles et espacements explicites restent prioritaires. L’aperçu conserve les 26 palettes et le fond blanc classique de l’original.</p><h2 id="widgets-et-fonctions-proches-de-l-original" tabindex="-1">Widgets et fonctions proches de l’original <a class="header-anchor" href="#widgets-et-fonctions-proches-de-l-original" aria-label="Permalink to &quot;Widgets et fonctions proches de l’original&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Famille</th><th>Fonctions et commandes</th></tr></thead><tbody><tr><td>Buttons / Icon Buttons</td><td>Textes/couleurs/icônes d’état, couleur à l’appui, bouton momentané, addition bornée, nouvelle fenêtre, navigation et déverrouillage temporisé</td></tr><tr><td>State Multi</td><td>Ancien cycle ou plusieurs entités avec valeurs et délais distincts</td></tr><tr><td>Checkbox / Switch</td><td>Valeurs MARCHE/ARRÊT ou mode booléen, position du libellé et véritable interrupteur</td></tr><tr><td>Input / Select / Autocomplete</td><td>Formes, affixes, aide/compteur, icônes, survol/sélection, clavier et masque : # = chiffre, A = lettre, * = lettre/chiffre</td></tr><tr><td>Slider / Slider Round</td><td>Poignée/piste, limites/pas, graduations, entité de travail, écriture pendant l’utilisation ou au relâchement, arc/angle initial</td></tr><tr><td>Progress</td><td>Linéaire/circulaire, déterminé/indéterminé, taille/rotation, seuils de couleurs et texte</td></tr><tr><td>Value / Icon / Version</td><td>Nombre/booléen/texte/date/durée, facteur/décalage, conditions, lien et effet ; icône statique ou d’état ; version réelle</td></tr><tr><td>HTML Card</td><td>Titre/sous-titre, image, dispositions, couleurs, actualisation d’image et HTML isolé</td></tr><tr><td>List / Icon List / Table / Alerts</td><td>Sous-textes, navigation/liens/commandes, barres d’état JSON, images, formatage, en-tête fixe, tri et acquittement</td></tr><tr><td>Quatre graphiques</td><td>Barres, secteurs/anneau, JSON et Recorder ; quatre axes Y, piles, remplissage/escaliers, infobulles, valeurs, palettes et légendes</td></tr><tr><td>Calendar</td><td>Mois/semaine/jour/année/liste, numéros de semaine, couleurs et grille horaire en DE/EN/FR</td></tr><tr><td>Top App Bar</td><td>Panneau modal/permanent/automatique, sous-entrées et index sélectionné ; anciens liens conservés dans un mode séparé</td></tr><tr><td>Grid/Masonry / Advanced Views</td><td>Colonnes adaptatives, visibilité par vue, associations/nom/index, booléens 0/1, préchargement et conservation des vues</td></tr></tbody></table><p><strong>Afficher les options avancées</strong> révèle les détails sans supprimer les valeurs masquées. Définir le nombre de cibles, vues, séries ou entrées souhaité.</p><h2 id="home-assistant-et-donnees" tabindex="-1">Home Assistant et données <a class="header-anchor" href="#home-assistant-et-donnees" aria-label="Permalink to &quot;Home Assistant et données&quot;">​</a></h2><p>Actions HA validées : <code>switch/input_boolean</code>, <code>number/input_number</code>, <code>text/input_text</code>, <code>select/input_select</code>, <code>button/input_button</code> avec <code>PRESS</code>, luminosité, pourcentage de ventilateur et position de volet. États, options et plages sont vérifiés. Capteurs, attributs et entités indisponibles restent en lecture seule.</p><p>Les actions multicibles sont séquentielles et s’arrêtent en cas d’erreur ou de changement de page. Les actions déjà exécutées ne sont pas annulées. Les services HA arbitraires et expressions ioBroker exécutables ne sont pas proposés.</p><p>Top App Bar en <strong>mode État</strong> écrit son index dans l’entité. <strong>Advanced View in Widget 8</strong>, avec la même entité et le <strong>mode Index</strong>, affiche la page Studio correspondante. Sans entité, utiliser le flux de données Studio existant ; les valeurs locales d’aperçu séparées ne sont pas partagées automatiquement.</p><p>Les listes lisent des lignes d’éditeur ou du JSON ; les tableaux utilisent les clés configurées. Le HTML facultatif des listes est nettoyé : sans scripts, gestionnaires d’événements ni contenus intégrés actifs. Les cartes HTML restent isolées. Les sites externes peuvent bloquer les iFrames.</p><p>Recorder est limité à <strong>dix entités et 1–168 heures</strong>. Les graphiques lisent <code>axisLabels/graphs</code>, <code>labels/datasets</code> ou des points. L’axe X respecte les intervalles réels. Agrégation : aucune, moyenne, minimum, maximum, somme ou dernière valeur ; intervalle en minutes. Aucun état manquant n’est inventé.</p><p>Pas d’import automatique de projets ioBroker : entités HA, Recorder et pages Studio remplacent objets, adaptateurs d’historique et vues VIS. Les graphiques SVG sont indépendants ; aucune identité universelle au pixel près n’est garantie.</p><h2 id="verifications-et-publication" tabindex="-1">Vérifications et publication <a class="header-anchor" href="#verifications-et-publication" aria-label="Permalink to &quot;Vérifications et publication&quot;">​</a></h2><p>Les tests navigateur couvrent les 49 entrées en DE/EN/FR, Classique/Material 3 et Clair/Sombre ainsi que les interactions. La mise à jour avec les vrais paquets conserve les projets à l’identique, octet par octet. Vérifier aussi les appareils dans sa propre installation HA.</p><p><a href="https://github.com/rockbaer2007/ha-grafik-visual-studio-materialdesign/blob/main/comparison/materialdesign-widgetvergleich.json" target="_blank" rel="noreferrer">Projet de comparaison</a> · <a href="https://github.com/rockbaer2007/ha-grafik-visual-studio-materialdesign/blob/main/comparison/AUDIT-2026-10-12.md" target="_blank" rel="noreferrer">Audit initial</a></p><p>Enregistrer <strong>1.1.0</strong>, Studio minimal <strong>0.1.292</strong>, ID <code>ugso.materialdesign</code> et MIT dans le <a href="https://visualstudio.ugso-software.de/?lang=fr" target="_blank" rel="noreferrer">catalogue</a>. Publier sur GitHub n’approuve pas automatiquement le paquet. Empreinte : <code>dist/SHA256SUMS</code>.</p>',25)])])}const m=t(r,[["render",n]]);export{g as __pageData,m as default};
